    |
    | Nothing was cut: every string here is the original, verbatim. That is also why
    | the Arabic side needed no new translation for the tooltips.
    */
    'hints' => [
        'billing_timing' => 'الإيجار يُحصَّل مقدمًا؛ أما رسوم الخدمة أو إعادة تحميل المرافق فتُحصَّل بعد انتهاء الشهر، حين تُعرف التكلفة أو قراءة العداد. ويذكر البند الشهر الذي يغطيه.',
        'does_not_prorate' => 'الإيجار يُسعَّر بالزمن، فمن ينتقل في منتصف الشهر يدفع جزءًا منه. أما رخصة اللافتة أو رسم الانتظار الثابت أو أتعاب الإدارة الثابتة فليست كذلك — يحتفظ بها المستأجر للشهر أيًّا كان يوم وصوله. بتفعيل هذا الخيار يُحاسب البند كاملًا عن أي شهر يمتد إليه العقد، ولا يُرد عند الإخلاء في منتصف الشهر.',
        'cash_flow_section' => 'حسابات المركز المالي وحدها هي التي تحمل بندًا. أما الإيرادات والمصروفات فتتجمع في صافي الربح الذي تبدأ منه القائمة.',
        'escalation_interval_months' => 'يُرحَّل التاريخ بهذا العدد من الشهور عند كل زيادة، محسوبًا من الزيادة السابقة — لذا فإن بندًا كل ١٨ شهرًا يتناوب بين تاريخين في السنة بدلًا من أن ينحرف.',
        'document_template_locale' => 'اكتب اللغتين. فالمستأجر الذي يقرأ الفاتورة بالعربية يرى النص العربي؛ وإن كُتبت لغة واحدة فقط استُخدمت هي، بدلًا من ترك فراغ في موضع شروط السداد.',
        'payroll_rate_note' => 'اذكر القرار أو المنشور الذي جاءت منه هذه الأرقام. فحين يُسأل أحدهم لاحقًا عن سبب احتساب مسير سابق بها، تكون الإجابة هنا لا في الذاكرة.',
        'subcategory_trade' => 'أمر العمل الناتج عن هذه المشكلة يذهب إلى ذلك التخصص، فيصل إلى السعر الصحيح للساعة وإلى المقاولين المؤهلين.',
        'vendor_document_blocks_dispatch' => 'المنع مخصَّص للمخاطر التي يتحملها المول — مقاول بلا تأمين داخل المول. أما الأوراق فتُتابَع بإلحاح ولا تُعطِّل إصلاحًا طارئًا.',
        'expense_category_ledger_account' => 'وجّه البند إلى حسابه الخاص فتذهب كل فاتورة لاحقة من نوعه إليه بدلًا من بند المصروفات الإدارية العام.',
        'payment_method_ledger_account' => 'حساب التسوية هنا يفصل يوم التحصيل عن يوم وصول النقدية للبنك، فتتطابق المطابقة البنكية.',
        'holiday_kind' => 'إغلاق = لا يعمل أحد. يوم مختصر = ساعات أقل، وهو حال رمضان.',
        'asset_currency' => 'بالجنيه فقط: لا يوجد سعر صرف في النظام، فأي عملة أخرى ستُرحَّل للدفاتر بنسبة ١:١.',
        'nte' => 'اتركه فارغًا لعدم وضع حد. اعتماد عرض يرفعه إلى قيمة العرض، وتجاوزه يظهر على أمر العمل ولا يُمنع.',
        'est_service_cost' => 'يحل محل قيمة العمل السابقة. غرامة نسبة من القيمة تقرأ هذا الحقل، وتقرأ التكلفة الفعلية للمقاول بعد وصول الفاتورة.',
        'standard_hourly_rate' => 'اتركه فارغًا فلا تُحتسب تكلفة عمالة لهذا التخصص — الرقم الغائب أفضل من رقم مُختلق.',
        'permit_valid_to' => 'التصريح الممتد ليوم كامل يُستخدم في السابعة مساءً بعد انصراف مسؤول السلامة. حدّده بالساعات التي يجري فيها العمل فعلًا.',
        'escalation_index_lag_months' => 'تنشر الجهة الإحصائية رقم الشهر بعد أسابيع، فلا يمكن لزيادة يناير أن تقرأ يناير. اكتب الفارق كما ينص العقد.',
        'utility_tariff' => 'يتبع العداد تعريفة حتى يُدخل تغيير السعر المقرر مرة واحدة بدلاً من إعادة كتابته على كل عداد. تُسعّر القراءات بالسعر النافذ في تاريخ القراءة نفسها، فتحتفظ القراءة المُدخلة بأثر رجعي بالسعر القديم.',
        'utility_effective_from' => 'تغيير السعر درجة جديدة على السلّم وليس تعديلاً للقديمة — وهذا ما يبقي القراءة السابقة قابلة للتفسير. تظل الدرجة نافذة حتى تبدأ التالية، فلا يوجد تاريخ انتهاء يمكن أن يُخطئ أحد فيه.',
        'utility_tariff_active' => 'إلغاء التنشيط يزيل التعريفة من قائمة اختيار العداد دون المساس بالعدادات المرتبطة بها أو بالقراءات التي سعّرتها.',
        'credit_unearned' => 'إشعار الخصم يُرحَّل بتاريخ الإنهاء نفسه، والفترة المقفلة ترفضه — فيبقى المستأجر مُحمَّلًا بمدة لن يشغلها.',
        'gross_sales' => 'اتركه فارغًا لتسجيل الصافي مباشرة كما في السابق. وبملئه يتحول الإقرار إلى شهادة: الإجمالي، والاستقطاعات، والصافي الذي يُحتسب عليه الإيجار النسبي.',
        'percentage_rent_sales_exclusions' => 'كل عقد تجزئة يعرّف «إجمالي المبيعات» بقائمة استثناءات، وهي أكثر البنود إثارة للنزاع. الضريبة لا تحتاج منحًا — فالمتجر يحصّلها للدولة — أما المرتجعات وبطاقات الهدايا والتحويلات بين الفروع وخصومات الموظفين فكلها تنازلات وافق عليها المالك.',
        'security_deposit_months' => 'التأمين المتفق عليه بـ«ثلاثة شهور إيجار» يجب أن يظل ثلاثة شهور. لو بقي ثابتًا، فإن زيادة سنوية 7% تُنزل تأمين 3× إلى 2.29× بحلول السنة الخامسة — يتقلّص الضمان في الوقت الذي يزيد فيه الخطر.',
        'percentage_rent_billing_frequency' => 'بند مستقل عن أساس الاحتساب. الربع سنوي والسنوي يُسوّيان بأثر لاحق: لا تصدر الفاتورة إلا بعد إقفال كل شهور الفترة.',
        'announcement_category' => 'يرتّب الإعلان في قائمة المستأجر ويجعل إعلان الطوارئ أحمر على هاتفه.',
        'announcement_pinned' => 'يُبقي الإعلان في أعلى قائمة المستأجر أيًا كان تاريخه.',
        'unit_owner_party' => 'مالك الوحدة مسجَّل كطرف، مثل المستأجر تمامًا — وهذا ما يتيح لنا فوترته وتحصيل مدفوعاته ومنحه البوابة.',
        'tenure_type' => 'التمليك بيع، وحق الانتفاع حق استخدام طويل. كلاهما يُفوتر بنفس الطريقة هنا — الفارق في كيفية انتهاء الحق.',
        'fee_basis' => '«المُحصَّل» هو الخيار الأأمن: احتساب الأتعاب على إيجار مفوتر ولم يُحصَّل يعني استردادها لاحقًا.',
        'tax_code_code' => 'حروف إنجليزية كبيرة وأرقام وشرطات سفلية. ثابت بعد الحفظ — أكواد الرسوم تشير إليه، فتغييره يُلغي تصنيف كل توريد مرتبط به.',
        'tax_family' => 'أي ضريبة مصرية هي. تحدِّد الحساب الذي تُرحَّل إليه، وفي حالة الخصم والتحصيل تحدِّد أن النسبة تُخصم من المستحق لا تُضاف إليه.',
        'tax_direction' => 'مبيعات: ضريبة تُحمَّل على المستأجر. مشتريات: ضريبة حمّلها علينا مورِّد وتُسترد في الإقرار. كل نسبة موجودة في الاتجاهين لأن لكلٍّ حسابًا مختلفًا وجانبًا مختلفًا في الإقرار.',
        'purchase_tax_override_reason' => 'الضريبة على هذا المستند تبعد أكثر من جنيه واحد عمّا يقتضيه كوده الضريبي. اذكر السبب — نسبة مختلفة، أو توريد معفى جزئيًا، أو مورِّد احتسبها على وعاء مختلف. يُسجَّل على المستند.',
        'tax_override_reason' => 'هذا السطر ليس بالنسبة التي يحملها كوده الضريبي في تاريخ الفاتورة. اذكر السبب — عقد ثبّت نسبة، أو مورِّد قرّب المبلغ بطريقة مختلفة. يُسجَّل على السطر.',
        'tax_treatment' => '«خاضع بنسبة» يحتسب النسبة السارية من السلّم. «معفى» و«خاضع بنسبة صفر» كلاهما لا يحتسب شيئًا، والفرق بينهما في الإقرار الضريبي — ولهذا يُخزَّنان منفصلين لا يُستنتجان من صفر على السطر.',
        'tax_posting_role' => 'الحساب الذي تُرحَّل إليه محصّلات هذه الضريبة، عبر خريطة الترحيل — فيرث الكود الجديد أي تخصيص على مستوى العقار تلقائيًا.',
        'statutory_reference' => 'القانون أو المادة التي تستند إليها هذه الضريبة. السؤال الذي يطرحه المراجع عن نسبة ضريبية ليس «كم» بل «بأي سند».',
        'tax_code_active' => 'الكود غير المفعَّل لا يظهر في أي قائمة اختيار. لا يمكن تفعيل كود خاضع قبل إدخال نسبته وتحديد حساب ترحيله — وإلا ظهر في القوائم دون أن يحتسب شيئًا.',
        'tax_effective_from' => 'اليوم الذي تبدأ فيه هذه النسبة. تظل سارية حتى تبدأ النسبة التالية — لا يوجد تاريخ انتهاء، حتى لا تتداخل الفترات أو تنشأ بينها فجوات.',
        'closing_balance' => 'ما يقول البنك إنه كان في الحساب في نهاية الفترة. وعنده تنتهي التسوية: الرصيد الختامي مضافًا إليه ما في الدفاتر ولم يظهر لدى البنك يجب أن يساوي الأستاذ.',
        'book_posting' => 'القيود على هذا الحساب، الأقرب مبلغًا أولًا، خلال أسبوع من تاريخ السطر. ولا تُعرض القيود المرتبطة سابقًا ولا المعاكسة في الاتجاه.',
        'bank_ledger_account' => 'أي حساب في الدليل يمثّل هذا البنك. الحسابات القابلة للترحيل فقط — فالحساب التجميعي لا يمكن مطابقته بكشف.',
        'approval_tier' => 'المستويات تتكامل مع الأدوار: يكتسب الدور صلاحيته بمنحه المستوى، فلا يوجد تسلسل ثانٍ يُدار على حدة.',
        'approval_rule_active' => 'الشريحة غير المفعّلة تُتجاهل. وإذا لم تشمل أي شريحة المبلغ، لزم أشد مستوى مُعرَّف لهذا النوع — فالبوابة تُغلق عند الشك ولا تُفتح.',
        'charge_code' => 'حروف إنجليزية صغيرة وأرقام وشرطة سفلية. لا يمكن تغييره بعد الحفظ — فهذه القيمة مخزَّنة في كل سطر فاتورة صدر به، وتغييرها يفصل السجل التاريخي. عدّل الاسم بالأسفل بدلًا منه.',
        'charge_code_role' => 'اتركه فارغًا للترحيل إلى الإيرادات المتنوعة. مناسب فقط للرسوم العارضة — وأي بند يتكرر يستحق حسابًا خاصًا به.',
        'charge_code_tax_code' => 'الضريبة التي تُفوتر بها هذه الرسوم. نسبتها — وتاريخ سريان تلك النسبة — على الكود الضريبي نفسه، فتغيير النسبة تعديل واحد يسري على كل الرسوم التي تستخدمه. اتركه فارغًا لرسم لم يُبتّ فيه بعد: يُحتسب بالنسبة القياسية ما لم يكن من التوريدات المعفاة افتراضًا. يسري على الرسوم الجديدة فقط — الفواتير الصادرة تحتفظ بنسبتها.',
        'charge_code_system' => 'محرك الفوترة يستدعي هذا الكود بالاسم، فلا يمكن إيقافه أو حذفه — يمكن فقط تعديل اسمه وحسابه.',
        'escalation_amount' => 'مبلغ الزيادة الشهرية الثابت المطبَّق في كل سنة تعاقدية — «يزيد الإيجار ٥٬٠٠٠ جنيه شهريًا كل سنة». يُستخدم بدلًا من النسبة وليس معها.',
        'escalation_floor_rate' => 'اختياري. لا تقل الزيادة عن هذه النسبة مهما كان مصدر الحساب — وهو شق «أيهما أكبر: التضخم أو ٣٪» في الصيغة المعتادة. اتركه فارغًا إذا لم يحدد العقد حدًا أدنى.',
        'escalation_ceiling_rate' => 'اختياري. تُحدَّد الزيادة بهذه النسبة — وهو شق «وبما لا يجاوز ١٠٪»، وحاجز يمنع نسبة مكتوبة بالخطأ من رفع الإيجار تلقائيًا. اتركه فارغًا إذا لم يحدد العقد حدًا أقصى.',
        'posting_role' => 'الدور الذي يرحّل إليه النظام بالاسم. اختره من القائمة — أي دور خارجها لا يطلبه الدفتر أبدًا.',
        'cam_cap_scope' => 'معظم الشروط تضع سقفًا للتكاليف القابلة للتحكم فقط وتستثني الضرائب والتأمين والمرافق. وضع سقف للإجمالي حماية تفوق ما تشترطه معظم العقود.',
        'percentage_rent_deductible_types' => 'رسوم تُخصم من الإيجار النسبي لنفس الفترة — بند «مستحق بما يتجاوز الصيانة والضرائب». اتركه فارغًا إذا لم يكن هناك خصم.',
        'percentage_rent_tier_from' => 'مستوى المبيعات الذي تبدأ عنده الشريحة. تبدأ الشريحة الأولى عادةً من 0 بنسبة 0% — وهذه هي نقطة التعادل.',
        'write_off_date' => 'تاريخ الاعتراف بالخسارة. يُرحَّل إلى دفتر الأستاذ بهذا التاريخ، لذا يجب أن يقع في فترة محاسبية مفتوحة.',
        'lease_option_latest_notice' => 'الموعد النهائي. بعد هذا التاريخ يسقط الحق — يُنبّه الفحص اليومي قبله ويسجّل الخيار كساقط بعد مروره.',
        'lease_option_encumbers' => 'يشير إلى أن هذه الوحدة محجوزة، فلا تُعرض على مستأجر آخر أثناء سريان الخيار.',
        'fit_out_scope' => 'المعيار السائد هو الإيجار الأساسي فقط — فالمول يواصل النظافة والأمن والتكييف للوحدة أثناء التجهيز، ولذلك تستمر هذه الاستردادات عادةً. اختر «كل شيء» فقط إذا نصّ العقد الموقّع على ذلك.',
        'bill_purchase_request' => 'اربط هذه الفاتورة بأمر الشراء الذي تسدده، فتُقفل بضاعتها حساب «بضاعة لم تُفوتر» بدلاً من تحميل المصروف مرة ثانية — فالاستلام أدخل المخزون بالفعل. اتركه فارغاً للمصروف العام. تظهر فقط أوامر الشراء المستلمة لنفس المورد ونفس العقار.',
        'inventory_unit_cost' => 'التكلفة المعيارية المستخدمة في تقييم كل استهلاك أو إهدار لهذا الصنف. يجب أن تكون موجبة: عند الصفر يخرج المخزون من المستودع دون ترحيل أي قيد إلى الأستاذ، ويُسعَّر صرف قطعة الغيار بما يطلب أدنى درجة في سلّم الاعتماد.',
        'account_code' => 'أرقام فقط. يُحدَّد الحساب الأب تلقائيًا من الكود (مثلاً 41102 يتبع 411). الرقم الأول: 1 أصول · 2 خصوم · 3 حقوق ملكية · 4 إيرادات · 5 مصروفات.',
        'reading_value' => 'القراءة الحالية للعداد. يتم احتساب الاستهلاك تلقائيًا من الفرق عن القراءة السابقة، ويمكن تعديله إذا تم تصفير العداد.',
        'tenant_address' => 'يظهر على الفواتير وفي دليل المستأجرين. قسم العنوان الضريبي هو ما يُرسل إلى مصلحة الضرائب.',
        'rent_pricing_basis' => 'السعر لكل متر مربع يعيد اشتقاق الإيجار كلما تغيّرت المساحة المؤجرة، ويتيح مقارنة الصفقات على أساس واحد.',
        'pool_code' => 'مفتاح مختصر لهذا المجمع — cam أو tax أو insurance أو hvac. العقار يشغّل عدة مجمعات في السنة، والكود هو ما يفرّق بينها.',
        'unit_area_locked' => 'تُحدَّد عند الإنشاء. استخدم إجراء «إعادة القياس» لتسجيل مسح جديد — فهو يؤرِّخ التغيير حتى تحتفظ تسويات الخدمات السابقة بالمساحة التي حُوسبت عليها.',
        'remeasure_effective_from' => 'تاريخ سريان القياس الجديد. تحتفظ الفترات السابقة له بالمساحة القديمة، فيبقى ما صدرت به الفواتير كما هو.',
        'participant_scope' => 'كل مستأجري العقار، أو فقط عقود منطقة واحدة — «الجميع يشارك في مصاريف الخدمة، لكن منطقة المطاعم وحدها تتحمّل تنظيف مصائد الشحوم».',
        'participant_area' => 'تشارك العقود التي لها وحدة في هذه المنطقة. تُقرأ من الوحدات، فالعقد الذي ينتقل يخرج من المجمع تلقائيًا.',
        'base_rent_monthly_edit_lock' => 'مقفل في وضع التعديل. استخدم إجراء «تعديل الإيجار» لمزامنة صف الرسوم المتكررة مع العقد ذرّياً.',
        'has_marketing_levy' => 'هل يدفع هذا المستأجر مساهمة صندوق التسويق (نسبة شهرية من الإيجار الأساسي تُضاف إلى الفاتورة). أوقفها للمستأجرين الذين اتفقوا على إعفائهم منها.',
        'possession_date' => 'تاريخ تسليم الوحدة للمستأجر وبدء أعمال التجهيز — وغالبًا يسبق بدء مدة العقد. يُسجَّل لتوثيق التسليم ولا يؤثر على الفوترة.',
        'rent_commencement_date' => 'تاريخ بدء احتساب الإيجار. اتركه فارغًا إذا لم توجد فترة إعفاء، فيُفوتر العقد من شهر بدايته. ونطاق الإعفاء يُحدَّد بالحقل التالي.',
        'billing_frequency' => 'عدد مرات إصدار الفواتير لهذا العقد. العقود ربع/نصف/السنوية تُدفع مقدمًا: فاتورة واحدة لكل دورة تغطي الربع/السنة كاملة (الإيجار + الخدمة + التسويق معًا). تبدأ الدورات من أول شهر فوترة للعقد. الافتراضي شهري. اضبطها قبل أول فاتورة — تُقفل بعد ذلك.',
        'service_charge_monthly_edit_lock' => 'مقفل في وضع التعديل. استخدم إجراء «تعديل الإيجار» لمزامنة صف الرسوم المتكررة مع العقد ذرّياً.',
        'percentage_rent_calculation_type' => 'كيفية احتساب الإيجار المرتبط بالمبيعات. النقطة الطبيعية = يدفع المستأجر الأكبر بين الإيجار الأساسي أو (المبيعات × النسبة) — اخترها لصفقات «الأكبر»؛ يُحتسب على المستأجر فقط المقدار الذي تتجاوز به (المبيعات × النسبة) الإيجار الأساسي. الاصطناعي = يدفع المستأجر الإيجار الأساسي بالإضافة إلى نسبة من المبيعات فوق حدٍّ متفق عليه: (المبيعات − الحد) × النسبة.',
        'percentage_rent_frequency' => 'متى تُعاد نقطة الاحتساب. شهري (الافتراضي) = يُطبَّق الحد (والإيجار الأساسي في الطريقة الطبيعية) على مبيعات كل شهر على حدة. سنوي = يكون الحد رقمًا سنويًّا؛ يحتسب كل شهر مُقفَل فقط الزيادة اللازمة لرفع إجمالي إيجار النسبة للسنة إلى الفائض التراكمي، فيُقاصّ الشهر القوي مع الأشهر الضعيفة بدل تحميله زيادةً. اضبط الحد كرقم سنوي عند اختيار «سنوي».',
        'percentage_rent_rate' => 'نسبة من المبيعات فوق الحد المستحقة كإيجار إضافي. النسب النموذجية: 5%–8% للمطاعم، 4%–6% للتجزئة.',
        'cam_estimated_collected' => 'إجمالي المُحصَّل التقديري للمصروفات المشتركة من المستأجرين عبر رسوم الخدمة الشهرية. الفرق = الفعلي − المُحصَّل يحدد تسوية نهاية العام.',
        'cam_admin_fee_pct' => 'رسوم الإدارة المضافة على حصة كل مستأجر من المصروفات المشتركة المستردة (مثلاً 10%). تُحتسب مع ضريبة قيمة مضافة 14% في حساب إيراد مستقل عند التسوية. اتركها فارغة لتمرير التكلفة دون رسوم.',
        'cam_recovery_vat_rate' => 'ضريبة القيمة المضافة على استرداد تكلفة المصروفات المشتركة (تسوية نهاية العام وأي رصيد ناتج عن تحصيل زائد). القيمة الافتراضية 14% لتطابق التقدير الشهري. اضبطها على 0% فقط للتمرير غير الخاضع للضريبة. تُجمَّد بمجرد احتساب أي تخصيص.',
        'rate_per_unit' => 'الجنيه لكل وحدة استهلاك (لكل ك.و.س أو م³ ...). التكلفة = الاستهلاك × هذه التعريفة. اتركها فارغة لعداد تراقبه دون إعادة تحميله على المستأجر (مثل عدادات المناطق المشتركة).',
        'show_occupied_units' => 'تضمين الوحدات المحجوزة أو التي لديها عقد إيجار نشط (مثلاً عند جدولة تجديد متداخل مع العقد الحالي).',
